<template><div class="space-y-6"><header><h1 class="text-2xl font-bold">Protection Center</h1><p class="text-sm text-gray-500">Recorded coverage and renewals. FinOS does not recommend insurance products.</p></header>
<div class="grid gap-4 sm:grid-cols-3"><StatCard label="Life cover" :value="money(total('Life'))"/><StatCard label="Health cover" :value="money(total('Health'))"/><StatCard label="Annual premium" :value="money(annualPremium)"/></div>
<form class="grid gap-3 rounded-xl border bg-white p-5 sm:grid-cols-3" @submit.prevent="add"><select v-model="form.policyType" class="rounded-lg border-gray-300"><option v-for="x in types" :key="x">{{x}}</option></select><input v-model="form.provider" required placeholder="Provider" class="rounded-lg border-gray-300"><input v-model.number="form.coverageAmount" min="0" type="number" placeholder="Coverage" class="rounded-lg border-gray-300"><input v-model.number="form.premiumAmount" min="0" type="number" placeholder="Premium" class="rounded-lg border-gray-300"><select v-model="form.premiumFrequency" class="rounded-lg border-gray-300"><option>Monthly</option><option>Quarterly</option><option>HalfYearly</option><option>Annual</option></select><input v-model="form.renewalDate" type="date" class="rounded-lg border-gray-300"><button class="rounded-lg bg-indigo-600 px-4 py-2 text-white">Add policy</button></form>
<div class="rounded-xl border bg-white p-5"><p v-if="!items.length" class="text-sm text-gray-500">No insurance policies recorded.</p><div v-for="p in items" :key="p.id" class="flex justify-between border-b py-3"><div><b>{{p.policyType}} · {{p.provider}}</b><p class="text-sm text-gray-500">{{money(p.coverageAmount)}} cover · renewal {{p.renewalDate||'not recorded'}}</p></div><button class="text-sm text-red-600" @click="remove(p.id)">Delete</button></div></div></div></template>
<script setup>import{computed,onMounted,reactive,ref}from'vue';import{insuranceApi}from'../api/insurance';import{formatMoney as money}from'../utils/formatters';import StatCard from'../components/StatCard.vue';const items=ref([]),types=['Life','Health','Vehicle','Property','Other'];const form=reactive({policyType:'Life',provider:'',coverageAmount:0,premiumAmount:0,premiumFrequency:'Annual',renewalDate:null,status:'Active'});const load=async()=>items.value=(await insuranceApi.list()).data?.data??[];const add=async()=>{await insuranceApi.add({...form});form.provider='';await load()};const remove=async id=>{await insuranceApi.remove(id);await load()};const total=t=>items.value.filter(x=>x.policyType===t&&x.status==='Active').reduce((s,x)=>s+Number(x.coverageAmount),0);const annualPremium=computed(()=>items.value.reduce((s,x)=>s+Number(x.premiumAmount)*({Monthly:12,Quarterly:4,HalfYearly:2,Annual:1}[x.premiumFrequency]||1),0));onMounted(load)</script>
